// 由 scripts/build-styles.mjs 从 styles.css 生成，勿手改
export const DEV_PICKER_CSS = "/* ===== 开发模式全站元素圈选（DevElementPicker，仅 development 渲染；紫色，区别于平台青绿色圈选） ===== */\n.dvp-toggle{\n  position:fixed;left:16px;bottom:16px;z-index:var(--dvp-z, 2147482000);height:34px;padding:0 12px;\n  touch-action:none;user-select:none;cursor:grab;\n  display:inline-flex;align-items:center;gap:7px;border-radius:18px;\n  border:1px solid rgba(124,58,237,.45);background:#faf5ff;color:#6d28d9;\n  font-size:12px;font-weight:700;cursor:pointer;box-shadow:0 4px 14px rgba(109,40,217,.18);\n}\n.dvp-toggle:hover{background:#f3e8ff}\n.dvp-toggle.dragging{cursor:grabbing;box-shadow:0 8px 22px rgba(109,40,217,.32);transition:none}\n.dvp-toggle.on{background:#7c3aed;border-color:#7c3aed;color:#fff}\n.dvp-count{\n  min-width:16px;height:16px;padding:0 4px;border-radius:8px;background:#ef4444;color:#fff;\n  font-size:10px;font-weight:700;font-style:normal;display:inline-flex;align-items:center;justify-content:center;\n}\n.dvp-hover{\n  position:fixed;z-index:calc(var(--dvp-z, var(--dvp-z, 2147482000)) + 100);pointer-events:none;box-sizing:border-box;\n  border:1px solid #7c3aed;border-radius:2px;background:rgba(124,58,237,.08);\n}\n.dvp-hover>i{position:absolute;width:6px;height:6px;border-color:#7c3aed;border-style:solid;border-width:0}\n.dvp-c-tl{left:-1px;top:-1px;border-left-width:2px;border-top-width:2px}\n.dvp-c-tr{right:-1px;top:-1px;border-right-width:2px;border-top-width:2px}\n.dvp-c-bl{left:-1px;bottom:-1px;border-left-width:2px;border-bottom-width:2px}\n.dvp-c-br{right:-1px;bottom:-1px;border-right-width:2px;border-bottom-width:2px}\n.dvp-label-hint{\n  margin-left:6px;padding-left:6px;border-left:1px solid rgba(255,255,255,.35);\n  font-weight:400;opacity:.85;\n}\n.dvp-label{\n  position:fixed;z-index:calc(var(--dvp-z, var(--dvp-z, 2147482000)) + 101);pointer-events:none;transform:translateY(-100%);\n  padding:2px 7px;border-radius:4px;background:#6d28d9;color:#fff;\n  font:600 11px/1.5 \"SF Mono\",Menlo,Consolas,monospace;white-space:nowrap;max-width:70vw;\n  overflow:hidden;text-overflow:ellipsis;margin-top:-2px;box-shadow:0 2px 8px rgba(109,40,217,.3);\n}\n.dvp-tray{\n  position:fixed;z-index:var(--dvp-z, 2147482000);width:400px;max-width:calc(100vw - 32px);\n  max-height:min(88vh, 660px);display:flex;flex-direction:column;gap:8px;\n  background:var(--card);border:1px solid rgba(124,58,237,.35);border-radius:10px;\n  box-shadow:0 10px 28px rgba(15,37,68,.18);padding:10px 12px;\n}\n/* 复制成功：框上方文字提示 + 结果行紫色闪动 */\n.dvp-notice.is-err{background:#dc2626;box-shadow:0 4px 12px rgba(220,38,38,.28)}\n.dvp-notice{\n  position:absolute;left:0;top:-27px;z-index:2;padding:3px 10px;border-radius:13px;\n  background:#16a34a;color:#fff;font-size:11px;font-weight:700;white-space:nowrap;\n  box-shadow:0 4px 12px rgba(22,163,74,.28);animation:dvp-notice-in .16s ease-out;\n}\n@keyframes dvp-notice-in{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}\n.dvp-tray-list li.is-flash .dvp-name{animation:dvp-flash .88s ease-out}\n.dvp-tray-list li.is-flash .dvp-idx{animation:dvp-flash-idx .88s ease-out}\n@keyframes dvp-flash{\n  0%{background:#ddd6fe;border-color:#7c3aed;box-shadow:0 0 0 3px rgba(124,58,237,.25);transform:scale(1.015)}\n  55%{background:#ede9fe;border-color:#a78bfa;box-shadow:0 0 0 1px rgba(124,58,237,.12);transform:scale(1)}\n  100%{background:#faf5ff;border-color:rgba(124,58,237,.22);box-shadow:none;transform:none}\n}\n/* 重复选择：已有那条用琥珀色抖一下（不弹文字） */\n.dvp-tray-list li.is-dup .dvp-name{animation:dvp-dup .7s ease-out}\n.dvp-tray-list li.is-dup .dvp-idx{animation:dvp-dup-idx .7s ease-out}\n@keyframes dvp-dup{\n  0%,100%{background:#faf5ff;border-color:rgba(124,58,237,.22);transform:none}\n  20%{background:#fef3c7;border-color:#f59e0b;transform:translateX(-3px)}\n  50%{background:#fde68a;border-color:#f59e0b;transform:translateX(3px)}\n  75%{background:#fef3c7;border-color:#f59e0b;transform:translateX(-1px)}\n}\n@keyframes dvp-dup-idx{0%,100%{background:#7c3aed}40%{background:#f59e0b;transform:scale(1.2)}}\n@keyframes dvp-flash-idx{\n  0%{background:#7c3aed;transform:scale(1.25)}\n  60%{background:#7c3aed;transform:scale(1.05)}\n  100%{background:#7c3aed;transform:none}\n}\n.dvp-tray-hd{display:flex;align-items:baseline;gap:8px;font-size:12px;color:var(--ink)}\n.dvp-tray-close{\n  margin-left:auto;border:none;background:none;color:var(--mut);cursor:pointer;\n  font-size:16px;line-height:1;padding:0 2px;border-radius:4px;\n}\n.dvp-tray-close:hover{color:#ef4444;background:rgba(239,68,68,.08)}\n.dvp-tray-route{color:var(--mut);font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n/* 单行约 47.4px + 行距 4px：留 512px 正好放下 10 条，第 11 条开始才出现滚动条 */\n.dvp-tray-list{list-style:none;margin:0;padding:0;overflow:auto;max-height:512px;display:flex;flex-direction:column;gap:4px}\n.dvp-tray-list li{display:flex;align-items:center;gap:6px;cursor:pointer;border-radius:5px;padding:1px 6px}\n/* 行 hover 不铺底色：序号徽标加深微放大 + 文本框描边高亮 */\n.dvp-tray-list li:hover .dvp-idx{background:#5b21b6;transform:scale(1.12)}\n.dvp-tray-list li:hover .dvp-name b{color:#6d28d9}\n.dvp-idx{\n  flex:none;min-width:16px;height:16px;padding:0 4px;border-radius:8px;\n  background:#7c3aed;color:#fff;font-size:10px;font-weight:700;font-style:normal;\n  display:inline-flex;align-items:center;justify-content:center;\n}\n.dvp-page{\n  flex:none;max-width:96px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;\n  font-size:10px;color:#6d28d9;background:#faf5ff;border:1px solid rgba(124,58,237,.2);\n  border-radius:4px;padding:1px 5px;\n}\n.dvp-name{\n  flex:1;min-width:0;display:flex;flex-direction:column;gap:1px;overflow:hidden;\n  /* 整块是一个可点击的“框”：点框 = 复制这一行 */\n  border:1px solid rgba(124,58,237,.22);border-radius:6px;background:#faf5ff;\n  padding:3px 7px;cursor:pointer;transition:border-color .12s,box-shadow .12s;\n}\n.dvp-tray-list li:hover .dvp-name{border-color:#7c3aed;box-shadow:0 0 0 1px rgba(124,58,237,.14)}\n.dvp-name b{\n  font-size:12px;color:var(--ink);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;\n}\n.dvp-name code{\n  font-size:10px;color:#6d28d9;opacity:.75;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;\n}\n.dvp-tray-list button{border:none;background:none;color:var(--mut);cursor:pointer;font-size:14px;line-height:1;padding:0 2px}\n.dvp-tray-list button:hover{color:#ef4444}\n.dvp-tray-ft{display:flex;gap:8px;justify-content:flex-end;align-items:center}\n.dvp-tip{margin-right:auto;color:var(--mut);font-size:10px;line-height:1.4;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.dvp-btn{height:28px;padding:0 12px;border-radius:7px;border:1px solid var(--line);background:var(--card);color:var(--ink2);font-size:12px;font-weight:600;cursor:pointer}\n.dvp-btn:hover{border-color:#7c3aed;color:#6d28d9}\n.dvp-btn.primary{background:#7c3aed;border-color:#7c3aed;color:#fff}\n.dvp-btn.primary:hover{background:#6d28d9;color:#fff}\n";
